window.__ModuleLoader__.load({
  id: 'dsh-pet',
  factory(require) {
    const React = require('react')
    const h = React.createElement

    const STORAGE_KEY = 'dsh-pet:v1'
    const SIZE = 160
    const EDGE = 12
    const IDLE_MS = 120000
    const DRAG_TILT = 7
    const BONK_MS = 420

    // Filled from assets/*.png by tools/embed-art.py, keyed "<form>/<state>".
    // A missing entry falls back to the placeholder drawing below.
    const ART = {
  'alt/hungry': 'data:image/png;base64,',
  'alt/intro': 'data:image/png;base64,',
  'alt/sleep': 'data:image/png;base64,',
  'alt/work': 'data:image/png;base64,',
  'mint/bright': 'data:image/png;base64,',
  'mint/eating': 'data:image/png;base64,',
  'mint/panic': 'data:image/png;base64,',
  'mint/peace': 'data:image/png;base64,',
  'mint/sleep': 'data:image/png;base64,',
  'mint/squint': 'data:image/png;base64,',
}

    // One form for now, so every visit shows the supplied artwork.
    // Add more entries here to alternate by visit parity again.
    const FORMS = [
      {
        id: 'mint',
        body: '#3fa78f',
        shade: '#2c8571',
        top: 'blob',
        states: [
          // Click order. The first entry is what a fresh visit shows.
          // `caption` renders as DOM text outside the mirror layer, so it stays readable
          // whichever way the pet faces.
          {
            id: 'peace',
            eyes: 'happy',
            mouth: 'big',
            caption: 'Ciallo~\n(∠・ω< )⌒★',
          },
          {
            id: 'bright',
            eyes: 'happy',
            mouth: 'big',
            caption: '难不成你其实很喜欢我\n唉，大大方方直说吧\n都怪我是个可爱的小肥鱼\n太有魅力了',
          },
          { id: 'squint', eyes: 'open', mouth: 'small', caption: '你目录里的 dsh 是什么…\n大烧货吗？' },
          {
            id: 'panic',
            eyes: 'wide',
            mouth: 'big',
            caption: '压力一只\n大肥鱼？',
          },
          {
            id: 'eating',
            eyes: 'happy',
            mouth: 'big',
            captionPos: 'top-right',
            captionLines: [
              { t: '事已至此', align: 'left' },
              { t: '先吃饭吧', align: 'left', offset: 16 },
            ],
          },
        ],
        idleState: { id: 'sleep', eyes: 'closed', mouth: 'sleep' },
      },
      {
        id: 'alt',
        body: '#3f6fd0',
        shade: '#2c4fa0',
        top: 'blob',
        scale: 1.6,
        states: [
          {
            id: 'intro',
            eyes: 'open',
            mouth: 'small',
            captionTone: 'pink',
            captionGap: 58,
            caption: '为什么又让我穿上这种衣服？\n…吃光你的token哦',
          },
          {
            id: 'hungry',
            eyes: 'open',
            mouth: 'small',
            captionTone: 'pink',
            captionGap: 58,
            caption: '好饿啊主人~\n赏点大米饭嘛',
          },
          {
            id: 'work',
            eyes: 'open',
            mouth: 'small',
            captionTone: 'pink',
            captionGap: 58,
            captionLines: [
              { t: '换上这个工作效率就会提高吗', align: 'center', rotate: -4 },
              { t: '……真是变态的要求', align: 'center', rotate: 4 },
            ],
          },
        ],
        idleState: {
          id: 'sleep',
          eyes: 'closed',
          mouth: 'sleep',
          captionPos: 'top-right',
          captionTone: 'pink',
          captionGap: 58,
          caption: '好困wu……还不能睡！',
        },
      },
    ]

    // Layers exist because one element can carry only one transform:
    // bob, sway, tilt and pop each need their own wrapper.
    const STYLE = [
      '@keyframes dsh-pet-bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}',
      '@keyframes dsh-pet-sway{0%,100%{transform:rotate(-2.4deg)}50%{transform:rotate(2.4deg)}}',
      '@keyframes dsh-pet-breathe{0%,100%{transform:scale(1)}50%{transform:scale(1.035)}}',
      // Bonked on the head: pushed down and squashed, then springs back.
      '@keyframes dsh-pet-bonk{0%{transform:translateY(0) scale(1,1)}22%{transform:translateY(4px) scale(1.12,0.84)}48%{transform:translateY(-3px) scale(0.94,1.08)}72%{transform:translateY(1px) scale(1.03,0.97)}100%{transform:translateY(0) scale(1,1)}}',
      '@media (prefers-reduced-motion: reduce){',
      '.dsh-pet-motion{animation:none !important}',
      '}',
    ].join('')

    // Caption colour sets; a state picks one with `captionTone`.
    const TONES = {
      blue: { color: '#1b4b9c', glow: 'rgba(120, 175, 255, 0.55)', shadow: 'rgba(16, 58, 143, 0.38)' },
      pink: { color: '#c3337a', glow: 'rgba(255, 148, 205, 0.62)', shadow: 'rgba(168, 24, 94, 0.42)' },
    }

    function readStore() {
      try {
        const raw = window.localStorage.getItem(STORAGE_KEY)
        const parsed = raw ? JSON.parse(raw) : null
        return parsed && typeof parsed === 'object' ? parsed : {}
      } catch (error) {
        return {}
      }
    }

    function writeStore(next) {
      try {
        window.localStorage.setItem(STORAGE_KEY, JSON.stringify(next))
      } catch (error) {
        /* storage unavailable: state stays in memory for this page */
      }
    }

    // One visit per loaded page, computed before React can render twice.
    let visit = null
    function bumpVisit() {
      if (visit) return visit
      const saved = readStore()
      const count = (Number(saved.count) || 0) + 1
      visit = { count: count, formIndex: (count - 1) % FORMS.length }
      saved.count = count
      writeStore(saved)
      return visit
    }

    function clamp(point) {
      const maxX = Math.max(0, (window.innerWidth || 0) - SIZE)
      const maxY = Math.max(0, (window.innerHeight || 0) - SIZE)
      return {
        x: Math.max(0, Math.min(maxX, point.x)),
        y: Math.max(0, Math.min(maxY, point.y)),
      }
    }

    function screenMid() {
      const screen = window.screen || {}
      return (screen.availWidth || screen.width || window.innerWidth || 1) / 2
    }

    function facingFor(point) {
      const centerX = (window.screenX || 0) + point.x + SIZE / 2
      return centerX < screenMid() ? 'right' : 'left'
    }

    function topShape(kind, fill) {
      if (kind === 'cat') {
        return [
          h('path', { key: 'ear-l', d: 'M19 19 L24 5 L33 16 Z', fill: fill }),
          h('path', { key: 'ear-r', d: 'M45 19 L40 5 L31 16 Z', fill: fill }),
        ]
      }
      if (kind === 'antenna') {
        return [
          h('path', { key: 'ant-l', d: 'M26 15 C 24 8 21 5 18 3', stroke: fill, strokeWidth: 2, fill: 'none', strokeLinecap: 'round' }),
          h('circle', { key: 'ant-l-dot', cx: 17.5, cy: 2.5, r: 2.4, fill: fill }),
          h('path', { key: 'ant-r', d: 'M38 15 C 40 8 43 5 46 3', stroke: fill, strokeWidth: 2, fill: 'none', strokeLinecap: 'round' }),
          h('circle', { key: 'ant-r-dot', cx: 46.5, cy: 2.5, r: 2.4, fill: fill }),
        ]
      }
      if (kind === 'horns') {
        return [
          h('path', { key: 'horn-l', d: 'M22 17 C 17 12 17 7 21 3', stroke: fill, strokeWidth: 3, fill: 'none', strokeLinecap: 'round' }),
          h('path', { key: 'horn-r', d: 'M42 17 C 47 12 47 7 43 3', stroke: fill, strokeWidth: 3, fill: 'none', strokeLinecap: 'round' }),
        ]
      }
      return null
    }

    function Eyes(props) {
      const ink = '#161a1f'
      if (props.kind === 'closed') {
        return [
          h('path', { key: 'e-l', d: 'M19 35 Q24 40 29 35', stroke: ink, strokeWidth: 2.2, fill: 'none', strokeLinecap: 'round' }),
          h('path', { key: 'e-r', d: 'M35 35 Q40 40 45 35', stroke: ink, strokeWidth: 2.2, fill: 'none', strokeLinecap: 'round' }),
        ]
      }
      if (props.kind === 'happy') {
        return [
          h('path', { key: 'e-l', d: 'M19 37 Q24 31 29 37', stroke: ink, strokeWidth: 2.4, fill: 'none', strokeLinecap: 'round' }),
          h('path', { key: 'e-r', d: 'M35 37 Q40 31 45 37', stroke: ink, strokeWidth: 2.4, fill: 'none', strokeLinecap: 'round' }),
        ]
      }
      const radius = props.kind === 'wide' ? 4.4 : 3.4
      const highlight = props.kind === 'wide' ? 1.4 : 1.1
      return [
        h('circle', { key: 'e-l', cx: 24, cy: 35, r: radius, fill: ink }),
        h('circle', { key: 'e-r', cx: 40, cy: 35, r: radius, fill: ink }),
        h('circle', { key: 'g-l', cx: 24 + radius * 0.38, cy: 35 - radius * 0.38, r: highlight, fill: '#ffffff' }),
        h('circle', { key: 'g-r', cx: 40 + radius * 0.38, cy: 35 - radius * 0.38, r: highlight, fill: '#ffffff' }),
      ]
    }

    function Mouth(props) {
      const ink = '#161a1f'
      if (props.kind === 'big') {
        return h('ellipse', { cx: 32, cy: 45, rx: 5.2, ry: 3.8, fill: ink, opacity: 0.72 })
      }
      if (props.kind === 'small') {
        return h('ellipse', { cx: 32, cy: 44, rx: 1.7, ry: 1.5, fill: ink, opacity: 0.68 })
      }
      if (props.kind === 'sleep') {
        return h('path', { d: 'M28 44 Q30 46 32 44 Q34 46 36 44', stroke: ink, strokeWidth: 1.8, fill: 'none', strokeLinecap: 'round', opacity: 0.6 })
      }
      return h('path', { d: 'M28 43.5 Q32 46.5 36 43.5', stroke: ink, strokeWidth: 2, fill: 'none', strokeLinecap: 'round', opacity: 0.72 })
    }

    function PlaceholderArt(props) {
      const form = props.form
      const state = props.state
      const asleep = props.asleep
      return h('svg', {
        viewBox: '0 0 64 64',
        width: SIZE,
        height: SIZE,
        'aria-hidden': true,
        style: { display: 'block' },
      },
        topShape(form.top, form.shade),
        h('ellipse', { cx: 32, cy: 37, rx: 24, ry: 21, fill: form.body }),
        h('ellipse', { cx: 23, cy: 31, rx: 9, ry: 6.5, fill: '#ffffff', opacity: 0.16 }),
        Eyes({ kind: state.eyes }),
        Mouth({ kind: state.mouth }),
        h('ellipse', { cx: 17, cy: 41, rx: 3.4, ry: 2.3, fill: '#e0728a', opacity: asleep ? 0.22 : 0.42 }),
        h('ellipse', { cx: 47, cy: 41, rx: 3.4, ry: 2.3, fill: '#e0728a', opacity: asleep ? 0.22 : 0.42 }),
        asleep
          ? h('text', {
              x: 50, y: 16, fontSize: 11, fill: form.shade, opacity: 0.85,
              fontFamily: 'ui-monospace, monospace', fontWeight: 700,
            }, 'z')
          : null
      )
    }

    function PetArt(props) {
      const src = ART[props.form.id + '/' + props.state.id] || ART['mint/' + props.state.id]
      if (src) {
        // Render at the scaled size instead of scaling a transform: transform would
        // resample an already-rasterised 160px layer and soften the artwork.
        const box = Math.round(SIZE * (props.form.scale || 1))
        return h('img', {
          src: src,
          width: box,
          height: box,
          alt: '',
          draggable: false,
          style: {
            display: 'block',
            position: 'absolute',
            left: '50%',
            top: '50%',
            width: box + 'px',
            height: box + 'px',
            objectFit: 'contain',
            transform: 'translate(-50%, -50%)',
          },
        })
      }
      return h(PlaceholderArt, props)
    }

    function Pet() {
      const info = bumpVisit()
      const form = FORMS[info.formIndex]

      const [pos, setPos] = React.useState(function () {
        const saved = readStore().pos
        if (saved && typeof saved.x === 'number' && typeof saved.y === 'number') return clamp(saved)
        return { x: EDGE, y: 140 }
      })
      const [facing, setFacing] = React.useState('right')
      const [dragging, setDragging] = React.useState(false)
      const [stateIndex, setStateIndex] = React.useState(0)
      const [asleep, setAsleep] = React.useState(false)
      const [tilt, setTilt] = React.useState(0)
      const [pulse, setPulse] = React.useState(0)

      const drag = React.useRef(null)
      const posRef = React.useRef(pos)
      const idleTimer = React.useRef(null)
      const bonkTimer = React.useRef(null)
      posRef.current = pos

      function armIdle() {
        if (idleTimer.current) window.clearTimeout(idleTimer.current)
        idleTimer.current = window.setTimeout(function () {
          idleTimer.current = null
          setAsleep(true)
        }, IDLE_MS)
      }

      function disarmIdle() {
        if (idleTimer.current) {
          window.clearTimeout(idleTimer.current)
          idleTimer.current = null
        }
      }

      React.useEffect(function () {
        setFacing(facingFor(posRef.current))
        armIdle()
        return function () {
          disarmIdle()
          if (bonkTimer.current) window.clearTimeout(bonkTimer.current)
        }
      }, [])

      React.useEffect(function () {
        function onMove(event) {
          const active = drag.current
          if (!active) return
          const next = clamp({
            x: active.originX + event.clientX - active.startX,
            y: active.originY + event.clientY - active.startY,
          })
          const dx = event.clientX - active.startX
          if (Math.abs(dx) > 3 || Math.abs(event.clientY - active.startY) > 3) {
            active.moved = true
          }
          active.last = next
          posRef.current = next
          setPos(next)
          setFacing(facingFor(next))
          if (Math.abs(dx) > 3) setTilt(dx > 0 ? DRAG_TILT : -DRAG_TILT)
        }
        function onUp() {
          const active = drag.current
          if (!active) return
          drag.current = null
          setDragging(false)
          setTilt(0)
          if (active.moved) {
            if (active.last) {
              const saved = readStore()
              saved.pos = active.last
              writeStore(saved)
            }
          } else {
            setAsleep(false)
            setPulse(function (n) { return n + 1 })
            // The state advances only after the bonk plays, so the hit reads first.
            if (bonkTimer.current) window.clearTimeout(bonkTimer.current)
            bonkTimer.current = window.setTimeout(function () {
              bonkTimer.current = null
              setStateIndex(function (i) { return (i + 1) % form.states.length })
            }, BONK_MS)
          }
          armIdle()
        }
        function onResize() {
          const next = clamp(posRef.current)
          if (next.x !== posRef.current.x || next.y !== posRef.current.y) {
            posRef.current = next
            setPos(next)
          }
          setFacing(facingFor(next))
        }
        window.addEventListener('pointermove', onMove)
        window.addEventListener('pointerup', onUp)
        window.addEventListener('pointercancel', onUp)
        window.addEventListener('resize', onResize)
        return function () {
          window.removeEventListener('pointermove', onMove)
          window.removeEventListener('pointerup', onUp)
          window.removeEventListener('pointercancel', onUp)
          window.removeEventListener('resize', onResize)
        }
      }, [])

      function onPointerDown(event) {
        if (event.button !== 0 && event.button != null) return
        event.preventDefault()
        drag.current = {
          startX: event.clientX,
          startY: event.clientY,
          originX: posRef.current.x,
          originY: posRef.current.y,
          last: null,
          moved: false,
        }
        setDragging(true)
      }

      const current = asleep ? form.idleState : form.states[stateIndex % form.states.length]
      const tone = TONES[current.captionTone] || TONES.blue

      return h('div', {
        style: {
          position: 'fixed',
          left: pos.x + 'px',
          top: pos.y + 'px',
          width: SIZE + 'px',
          height: SIZE + 'px',
          pointerEvents: 'auto',
          touchAction: 'none',
          userSelect: 'none',
          cursor: dragging ? 'grabbing' : 'pointer',
          filter: 'drop-shadow(0 6px 12px rgba(0, 0, 0, 0.3))',
        },
        onPointerDown: onPointerDown,
        title: form.id + ' · ' + current.id,
      },
        h('style', { dangerouslySetInnerHTML: { __html: STYLE } }),

        h('div', { style: { transform: 'scaleX(' + (facing === 'left' ? -1 : 1) + ')' } },

          h('div', {
            className: 'dsh-pet-motion',
            style: { animation: asleep ? 'dsh-pet-breathe 4.4s ease-in-out infinite' : 'dsh-pet-bob 3.2s ease-in-out infinite' },
          },

            h('div', {
              className: 'dsh-pet-motion',
              style: { animation: asleep ? 'none' : 'dsh-pet-sway 5.6s ease-in-out infinite' },
            },

              h('div', {
                style: {
                  transform: 'rotate(' + tilt + 'deg)',
                  transition: dragging ? 'transform 90ms linear' : 'transform 220ms ease-out',
                  opacity: asleep ? 0.9 : 1,
                },
              },

                h('div', {
                  key: pulse,
                  className: 'dsh-pet-motion',
                  style: { position: 'relative', width: SIZE + 'px', height: SIZE + 'px', animation: 'dsh-pet-bonk ' + BONK_MS + 'ms ease-out' },
                },
                  h(PetArt, { form: form, state: current, asleep: asleep })
                )
              )
            )
          )
        ),

        // Caption sits outside the mirror layer, so it never renders reversed.
        (current.caption || current.captionLines)
          ? h('div', {
              style: Object.assign({
                position: 'absolute',
                bottom: '100%',
                marginBottom: (current.captionGap || 2) + 'px',
                width: 'max-content',
                maxWidth: '250px',
                font: '800 12px/1.45 "HarmonyOS Sans SC", "Microsoft YaHei", "PingFang SC", sans-serif',
                whiteSpace: 'pre-line',
                letterSpacing: '0.6px',
                color: tone.color,
                WebkitTextStroke: '3.5px #ffffff',
                paintOrder: 'stroke fill',
                textShadow: '0 1px 0 #ffffff, 0 0 6px ' + tone.glow + ', 0 3px 6px ' + tone.shadow,
                pointerEvents: 'none',
                userSelect: 'none',
              },
                current.captionPos === 'top-right'
                  ? { right: '0px', textAlign: 'right' }
                  : { left: '50%', transform: 'translateX(-50%) rotate(-2deg)', textAlign: 'center' }),
            },
              current.captionLines
                ? current.captionLines.map(function (line, index) {
                    var shift = line.offset ? ' translateX(' + line.offset + 'px)' : ''
                    var tilt = line.rotate ? ' rotate(' + line.rotate + 'deg)' : ''
                    return h('div', {
                      key: index,
                      style: {
                        textAlign: line.align,
                        transform: (shift + tilt).trim() || 'none',
                      },
                    }, line.t)
                  })
                : current.caption
            )
          : null
      )
    }

    return {
      inject: ['slots'],
      apply(ctx) {
        ctx.slots.inject('shell.overlay', function () {
          return ctx.slots.register({
            name: 'shell.overlay',
            id: 'dsh-pet',
            order: 100,
          }, Pet)
        })
      },
    }
  },
})
